      'コメント送信がうまくいっているかを状態速報の診断JSON(commentSubmitDiag)で見られるようにしました。試行回数・成功回数・失敗回数・成功率・直近の所要時間(平均/最大)・直近の失敗理由を集計します。失敗理由は「入力欄が見つからない」「送信ボタンが見つからない」「送信を確認できなかった」などに分類されます。集計はメモリ上で行い、ストレージの読み込みは増やさないため、状態速報ページの軽さに影響しません(送信が一度も行われていなければ何も出ません)。'
